"""Native NAP Dash Sentry controls and authenticated evidence browser."""
PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NAP Sentry</title><style>
:root{color-scheme:dark;--text:#eaf4f5;--muted:#a5bdc5;--cyan:#55d6d1}*{box-sizing:border-box}body{background:radial-gradient(circle at 38% 0%,#142e36,#09141a 50%,#070b0f);color:var(--text);font:16px system-ui;margin:0}.shell{max-width:1440px;margin:auto;padding:18px}.brand{font-size:1.6rem;font-weight:900}.brand span,a{color:var(--cyan)}.tabs{display:flex;gap:5px;border:1px solid #29414a;border-radius:15px;background:#0e1a20;padding:5px;margin:14px 0}.tabs a{text-decoration:none;padding:12px 16px;text-transform:uppercase;letter-spacing:.07em;font-size:.78rem;font-weight:850;border-radius:10px;color:var(--muted)}.tabs .active{background:var(--cyan);color:#062027}.card{background:linear-gradient(145deg,#152128,#10171c);border:1px solid #29414a;border-radius:16px;padding:16px;margin-bottom:14px}.controls{display:flex;align-items:center;flex-wrap:wrap;gap:8px}button,input,select{font:inherit;padding:11px 13px;border:1px solid #34505a;border-radius:10px;background:#192a31;color:inherit}button{cursor:pointer;font-weight:750}button.primary{background:var(--cyan);color:#062027}input.pin{width:140px}input[type=checkbox]{accent-color:var(--cyan)}label{display:inline-flex;align-items:center;gap:6px;font-size:.85rem}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px;margin-bottom:14px}.metric{background:#101b20;border:1px solid #29414a;border-radius:12px;padding:12px}.metric span,h2{font-size:.75rem;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}.metric b{display:block;font-size:1.15rem;margin-top:6px}h2{margin:0 0 12px}.sub{color:var(--muted);font-size:.85rem}.cameras,.events{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:12px}.camera{background:#101b20;border:1px solid #29414a;border-radius:14px;padding:12px}.camera[hidden]{display:none}video{width:100%;aspect-ratio:16/9;object-fit:contain;background:#000;border-radius:8px}.event img{width:100%;border-radius:8px;aspect-ratio:16/9;object-fit:contain;background:#000}.event .controls{margin-top:12px}.bad{color:#ff827c}.good{color:#70d68b}.settings{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}.settings label{display:flex;flex-direction:column;align-items:stretch}.settings input{width:100%}summary{cursor:pointer;font-weight:750}#status{min-height:24px}#playback[hidden]{display:none}</style></head><body><div class="shell">
<header><div class="brand">NAP <span>Sentry</span></div><div class="sub">Parked security · three live cameras · efficient front-camera evidence</div></header><nav class="tabs"><a href="/">Home</a><a class="active" href="/sentry" aria-current="page">Sentry</a></nav>
<section class="card"><div class="controls"><input id="key" class="pin" type="password" inputmode="numeric" maxlength="6" placeholder="6-digit PIN" autocomplete="off" aria-label="Sentry PIN"><label><input id="remember" type="checkbox" checked>Remember on this browser</label><button id="unlock">Connect</button><button id="forget">Forget PIN</button></div><p id="status" role="status">Enter your PIN to connect. Automatically monitors while offroad when power and temperature permit.</p><div class="controls"><button id="arm" class="primary">Resume monitoring</button><button id="disarm">Pause until next drive</button><label><input id="auto" type="checkbox" checked>Auto-arm when offroad</label><button id="start">Live view</button><button id="stop">Stop live view</button><button id="snapshot">Snapshot</button><button id="record">Manual record</button><button id="record-stop">Stop recording</button><label><input id="motion" type="checkbox" checked>Motion detection</label><select id="view" aria-label="Camera view"><option value="all">All cameras</option><option value="road">Front</option><option value="wideRoad">Wide front</option><option value="driver">Cabin</option></select></div></section>
<div class="metrics"><div class="metric"><span>Security</span><b id="state">DISARMED</b></div><div class="metric"><span>Camera</span><b id="camera">Off</b></div><div class="metric"><span>Temperature</span><b id="temp">—</b></div><div class="metric"><span>Protection</span><b id="thermal">—</b></div><div class="metric"><span>Device input</span><b id="power">—</b></div><div class="metric"><span>Storage / events</span><b id="storage">—</b></div><div class="metric"><span>Remote connection</span><b id="connection">Disconnected</b></div><div class="metric"><span>Monitoring / live timer</span><b id="remaining">—</b></div></div>
<div class="cameras"><section class="camera" data-camera="road"><h2>Front</h2><video id="video-road" autoplay playsinline muted controls></video></section><section class="camera" data-camera="wideRoad"><h2>Wide front</h2><video id="video-wideRoad" autoplay playsinline muted controls></video></section><section class="camera" data-camera="driver"><h2>Cabin</h2><video id="video-driver" autoplay playsinline muted controls></video></section></div>
<p class="sub">Live viewing stops after five minutes or disconnection. Automatic monitoring continues while offroad and safe. It does not require an open browser. Snapshots and event clips use the front camera; thumbnails are grayscale. Direct private/Tailscale access is required for live media.</p>
<section class="card" id="playback" hidden><h2>Event playback</h2><video id="event-video" controls playsinline></video><button id="close-playback">Close playback</button></section>
<section class="card"><div class="controls"><h2 style="margin:0">Security events</h2><button id="refresh">Refresh</button><span id="event-count" class="sub"></span></div><p class="sub">Events expire after 24 hours unless protected. Storage limits may remove oldest unprotected events sooner. Driving logs are kept separately.</p><div id="events" class="events"></div><button id="older" hidden>Show older events</button></section>
<details class="card"><summary>Settings and measured sensors</summary><p class="sub">Disarm and stop live viewing before saving. Hardware camera power remains significant even with low-rate motion analysis.</p><div id="settings" class="settings"></div><button id="save-settings">Save settings</button><p id="sensors" class="sub"></p></details>
</div><script>
const el=id=>document.getElementById(id),cameras=['road','wideRoad','driver'],storageKey='nap-sentry-pin';let pc=null,running=false,busy=false,generation=0,connected=false,pollBusy=false,refreshTick=0,lastSignature='',lastConfig='',urls=[],playbackUrl=null,visibleEvents=30;
try{el('key').value=localStorage.getItem(storageKey)||''}catch(e){}
function remember(){try{if(el('remember').checked)localStorage.setItem(storageKey,el('key').value);else localStorage.removeItem(storageKey)}catch(e){}}
function message(t,bad=false){el('status').textContent=t;el('status').className=bad?'bad':''}
async function api(op,body,blob=false){let r=await fetch('/api/sentry/'+op,{method:body?'POST':'GET',headers:{'Authorization':'Bearer '+el('key').value,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok){let d=await r.json();if(r.status===401){connected=false;el('connection').textContent='PIN required'}throw Error(d.error||r.status)}return blob?r.blob():r.json()}
function close(){generation++;running=false;if(pc){pc.onconnectionstatechange=null;pc.close()}pc=null;cameras.forEach(c=>el('video-'+c).srcObject=null)}
async function stop(){close();await api('stop',{});await status();message('Live view stopped')}
async function action(op,body={}){try{await api(op,body);remember();connected=true;await status();await history();message(op==='arm'?'Monitoring resumed; allow several seconds for camera warmup':op==='snapshot'?'Snapshot requested; it will appear in events':op==='record_start'?'Recording requested; it will appear in events':'Updated')}catch(e){message(e.message,true)}}
el('remember').onchange=()=>{if(!el('remember').checked){try{localStorage.removeItem(storageKey)}catch(e){}}};
el('forget').onclick=async()=>{if(running){try{await stop()}catch(e){close()}}try{localStorage.removeItem(storageKey)}catch(e){}el('key').value='';el('remember').checked=false;connected=false;message('Saved PIN forgotten')};
el('unlock').onclick=async()=>{try{await status();connected=true;remember();await history();message('Connected')}catch(e){message(e.message,true)}};
el('auto').onchange=()=>action('auto',{enabled:el('auto').checked});el('arm').onclick=()=>action('arm');el('disarm').onclick=async()=>{close();await action('disarm')};el('snapshot').onclick=()=>action('snapshot');el('record').onclick=()=>action('record_start');el('record-stop').onclick=()=>action('record_stop');el('motion').onchange=()=>action('motion',{enabled:el('motion').checked});el('stop').onclick=()=>stop().catch(e=>message(e.message,true));
el('view').onchange=()=>document.querySelectorAll('[data-camera]').forEach(tile=>tile.hidden=el('view').value!=='all'&&tile.dataset.camera!==el('view').value);
el('start').onclick=async()=>{if(busy||running)return;busy=true;try{if(!/^[0-9]{6}$/.test(el('key').value))throw Error('Enter a six-digit PIN');await api('start',{});remember();connected=true;running=true;const current=++generation;message('Starting cameras…');await new Promise(r=>setTimeout(r,5000));if(current!==generation)return;const peer=new RTCPeerConnection({iceServers:[]});pc=peer;const ts=cameras.map(()=>peer.addTransceiver('video',{direction:'recvonly'}));peer.ontrack=e=>{if(current!==generation)return;let cam=cameras.find(c=>e.track.id.startsWith(c+':'))||cameras[ts.indexOf(e.transceiver)];if(cam){el('video-'+cam).srcObject=new MediaStream([e.track]);el('video-'+cam).play().catch(()=>{})}};peer.onconnectionstatechange=()=>{if(current===generation&&['failed','closed'].includes(peer.connectionState))stop().catch(()=>close())};await peer.setLocalDescription(await peer.createOffer());await new Promise((resolve,reject)=>{if(peer.iceGatheringState==='complete')return resolve();let t=setTimeout(()=>reject(Error('ICE gathering timed out')),8000);peer.addEventListener('icegatheringstatechange',()=>{if(peer.iceGatheringState==='complete'){clearTimeout(t);resolve()}})});if(current!==generation)return;let answer=await api('offer',{sdp:peer.localDescription.sdp});if(current!==generation)return;await peer.setRemoteDescription(answer);message('Connecting cameras over your private network…');setTimeout(()=>{if(current===generation&&peer.connectionState!=='connected'){stop().catch(()=>close());message('Camera connection timed out',true)}},20000)}catch(e){try{await stop()}catch(_){close()}message(e.message,true)}finally{busy=false}};
const fields={analysis_fps:'Analysis frames / second',pixel_threshold:'Pixel difference threshold',changed_fraction:'Changed image fraction',confirmation_frames:'Consecutive confirmations',brightness_jump:'Global brightness threshold',clip_seconds:'Event tail seconds',max_clip_seconds:'Maximum clip seconds',cooldown_seconds:'Trigger cooldown seconds',storage_mb:'Security allowance MB',reserve_mb:'Free-space reserve MB',warn_c:'Reduce activity °C',suspend_c:'Suspend activity °C',width:'Encoder width',height:'Encoder height',fps:'Encoder frames / second',bitrate:'Encoder bitrate'};
async function status(){let d=await api('status');connected=true;el('state').textContent=d.state.toUpperCase();el('camera').textContent=d.camera?'Frames arriving':'Off / starting';el('temp').textContent=d.metrics.max_c==null?'—':d.metrics.max_c.toFixed(1)+' °C';el('thermal').textContent=d.state==='suspended'?'SUSPENDED':d.warning?'REDUCED ACTIVITY':d.safe?'Ready':'Not permitted';el('thermal').className=d.safe&&!d.warning?'good':'bad';el('power').textContent=d.metrics.input_w==null?'Unavailable':d.metrics.input_w.toFixed(2)+' W';el('storage').textContent=(d.storage.used_bytes/1048576).toFixed(1)+' / '+d.config.storage_mb+' MB · '+d.storage.event_count;el('storage').title=(d.storage.free_bytes/1073741824).toFixed(2)+' GB free';el('connection').textContent=pc?pc.connectionState:'Dash connected';el('auto').checked=d.auto_enabled;el('remaining').textContent=d.active?d.remaining+' sec live':d.auto_armed?'While offroad':d.paused?'Paused until next drive':d.fault_blocked?'Check camera / resume':d.armed?Math.ceil(d.armed_remaining/60)+' min manual':d.auto_enabled?'Automatic · waiting':'Manual mode';el('motion').checked=d.motion;el('sensors').textContent=Object.entries(d.metrics.sensors||{}).map(([k,v])=>k+': '+v+' °C').join(' · ');if(d.reason||d.worker.error)message(d.reason||d.worker.error,true);if(running&&!d.active){close();message(d.reason||'Live session ended')}let sig=JSON.stringify(d.config);if(sig!==lastConfig){lastConfig=sig;el('settings').replaceChildren();Object.entries(fields).forEach(([key,label])=>{let l=document.createElement('label');l.textContent=label;let i=document.createElement('input');i.type='number';i.step=key==='changed_fraction'?'.005':'1';i.id='cfg-'+key;i.value=d.config[key];l.append(i);el('settings').append(l)})}return d}
el('save-settings').onclick=()=>{let body={};Object.keys(fields).forEach(k=>body[k]=Number(el('cfg-'+k).value));action('config',body)};
function revoke(){urls.forEach(u=>URL.revokeObjectURL(u));urls=[]}
function closePlayback(){el('event-video').pause();el('event-video').removeAttribute('src');el('event-video').load();if(playbackUrl)URL.revokeObjectURL(playbackUrl);playbackUrl=null;el('playback').hidden=true}
el('close-playback').onclick=closePlayback;
async function history(){let d=await api('events'),rows=d.events||[];el('event-count').textContent=d.storage.event_count+' events · '+(d.storage.used_bytes/1048576).toFixed(1)+' MB';let signature=JSON.stringify(rows);if(signature===lastSignature)return;lastSignature=signature;revoke();el('events').replaceChildren();for(const event of rows.slice(0,visibleEvents)){let box=document.createElement('article');box.className='event card';let title=document.createElement('h2');title.textContent=new Date(event.timestamp*1000).toLocaleString();box.append(title);let img=document.createElement('img');img.alt=event.kind+' event thumbnail';box.append(img);api('media/'+event.id+'/thumbnail',null,true).then(blob=>{if(!box.isConnected)return;let u=URL.createObjectURL(blob);urls.push(u);img.src=u}).catch(()=>img.remove());let info=document.createElement('p');info.className='sub';info.textContent=event.kind+' · '+event.state+(event.duration_s?' · '+Math.round(event.duration_s)+' s':'')+(event.protected?' · Protected':event.expires_at?' · expires '+new Date(event.expires_at*1000).toLocaleString():'');box.append(info);let buttons=document.createElement('div');buttons.className='controls';if(event.state==='ready'){let play=document.createElement('button');play.textContent='Play';play.onclick=async()=>{try{closePlayback();playbackUrl=URL.createObjectURL(await api('media/'+event.id+'/video',null,true));el('event-video').src=playbackUrl;el('playback').hidden=false;el('event-video').play().catch(()=>{})}catch(e){message(e.message,true)}};buttons.append(play)}let protect=document.createElement('button');protect.textContent=event.protected?'Unprotect':'Protect';protect.onclick=()=>action('protect',{id:event.id,protected:!event.protected});buttons.append(protect);let del=document.createElement('button');del.textContent='Delete';del.disabled=['recording','finalizing'].includes(event.state);del.onclick=()=>{if(confirm('Delete this security event?'))action('delete',{id:event.id})};buttons.append(del);box.append(buttons);el('events').append(box)}el('older').hidden=rows.length<=visibleEvents;if(!rows.length)el('events').textContent='No security events in the last 24 hours'}
el('older').onclick=()=>{visibleEvents+=30;lastSignature='';history().catch(e=>message(e.message,true))};
el('refresh').onclick=()=>history().catch(e=>message(e.message,true));
setInterval(async()=>{if(pollBusy||!el('key').value)return;pollBusy=true;try{if(running)await api('ping',{});await status();if(refreshTick++%3===0)await history()}catch(e){el('connection').textContent='Disconnected';message(e.message,true);if(running)close()}finally{pollBusy=false}},2000);
window.addEventListener('pagehide',()=>{revoke();closePlayback();if(running){close();fetch('/api/sentry/stop',{method:'POST',headers:{'Authorization':'Bearer '+el('key').value,'Content-Type':'application/json'},body:'{}',keepalive:true}).catch(()=>{})}});
</script></body></html>'''
